fn sum(a: &Vec<u32>, b: &Vec<u32>) -> Vec<u32> {
    // We assume a.len() == b.len() and each pairwise sum < 1000.
    let n = a.len();
    let mut c = Vec::with_capacity(n);
    for i in 0..n {
        // Since each sum is guaranteed < 1000, no overflow can occur.
        c.push(a[i] + b[i]);
    }
    c
}

